<?php
/* Pages that need no account: membership interest, volunteer application, Academic Board review, manifest, privacy, about, scheduled job. */
declare(strict_types=1);

function public_shell(string $title, string $inner, string $sub = ''): never {
    page($title, '<div class="au-top"><a href="' . url('') . '"><img src="' . asset('logo.jpg') . '" alt="WODDI logo"></a><div class="grow"><b style="font-family:Manrope,sans-serif">WODDI Institute</b><div class="xs mut">' . e($sub ?: $title) . '</div></div>' . (me() ? '<a class="b g s" href="' . url('') . '">Open the app</a>' : '<a class="b g s" href="' . url('login') . '">Sign in</a>') . '</div><div class="au-wrap"><div class="au-card" style="max-width:760px">' . implode('', array_map(fn($f) => '<div class="flash ' . e($f[0]) . '">' . e($f[1]) . '</div>', flash())) . $inner . '</div></div>', ['bare' => true]);
}

if ($first === 'manifest.json') {
    header('Content-Type: application/manifest+json; charset=utf-8'); header('Cache-Control: public, max-age=3600');
    $b = rtrim((string)parse_url(base(), PHP_URL_PATH), '/') . '/';
    echo json_encode(['name' => 'WODDI Institute', 'short_name' => 'WODDI', 'description' => 'Learn, grow and earn certificates with WODDI Institute.', 'id' => $b, 'start_url' => $b, 'scope' => $b, 'display' => 'standalone', 'orientation' => 'portrait', 'background_color' => '#FBF7F4', 'theme_color' => '#2A0F2B', 'lang' => 'en', 'categories' => ['education'],
        'icons' => [['src' => asset('icon-192.png'), 'sizes' => '192x192', 'type' => 'image/png', 'purpose' => 'any'], ['src' => asset('icon-512.png'), 'sizes' => '512x512', 'type' => 'image/png', 'purpose' => 'any'], ['src' => asset('icon-maskable-192.png'), 'sizes' => '192x192', 'type' => 'image/png', 'purpose' => 'maskable'], ['src' => asset('icon-maskable-512.png'), 'sizes' => '512x512', 'type' => 'image/png', 'purpose' => 'maskable']],
        'shortcuts' => [['name' => 'Course Hub', 'url' => $b . 'learn'], ['name' => 'Community', 'url' => $b . 'community'], ['name' => 'Mentor', 'url' => $b . 'mentor']]], JSON_UNESCAPED_SLASHES);
    exit;
}
if ($first === 'offline') public_shell('You are offline', '<h1>You are offline</h1><p class="mut">Check your data or Wi-Fi, then try again. Lessons you already opened may still be readable.</p><a class="b au-b" href="' . url('') . '">Try again</a>');

/* The scheduled job. cPanel calls this address every 15 minutes with the secret key from config.php. */
if ($first === 'tick') {
    header('Content-Type: text/plain; charset=utf-8');
    if (!cfg('cron_key') || !hash_equals((string)cfg('cron_key'), (string)($_GET['key'] ?? ''))) { http_response_code(403); exit('Wrong key.'); }
    require_once APP_ROOT . '/lib/ops.php'; @set_time_limit(120); ignore_user_abort(true);
    $out = ['campaigns' => campaign_run(35), 'events' => event_reminders_run()];
    $last = (string)setting('reminders_last_run', ''); if ($last < gmdate('Y-m-d H:i:s', time() - 6 * 3600)) { $out['reminders'] = reminders_run(60); q('REPLACE INTO system_settings (`key`, value, updated_at) VALUES (?,?,?)', ['reminders_last_run', now(), now()]); }
    q('DELETE FROM password_resets WHERE expires_at < ?', [now()]);
    foreach (glob(APP_ROOT . '/storage/sessions/sess_*') ?: [] as $f) if (@filemtime($f) < time() - 30 * 86400) @unlink($f);
    q('REPLACE INTO system_settings (`key`, value, updated_at) VALUES (?,?,?)', ['cron_last_run', now() . ' GMT', now()]);
    exit('OK ' . json_encode($out));
}

if ($first === 'privacy' || $first === 'about') {
    $html = (string)@file_get_contents(APP_ROOT . "/content/pages/$first.html");
    public_shell($first === 'privacy' ? 'Privacy policy' : 'About WODDI', '<h1>' . ($first === 'privacy' ? 'Privacy policy' : 'About WODDI') . '</h1><div class="prose">' . $html . '</div>' . ($first === 'privacy' ? '<p class="sm mut">To delete your account and data, open Settings in the app and choose Delete account and data, or email support@thewoddi.org.</p>' : ''));
}

if ($first === 'membership') {
    if (is_post()) {
        if (post('website') !== '') redirect('membership', ['done' => 1]); /* honeypot */
        if (!filter_var(post('email'), FILTER_VALIDATE_EMAIL) || trim((string)post('full_name')) === '' || !post('consent_correct')) { flash('Add your name, a valid email, and tick the confirmation box.', 'err'); redirect('membership'); }
        ins('membership_interest', ['full_name' => mb_substr((string)post('full_name'), 0, 160), 'email' => strtolower((string)post('email')), 'phone' => post('phone'), 'dob' => post('dob') ?: null, 'age_bracket' => post('age_bracket'), 'country' => post('country'), 'state' => post('state'), 'city' => post('city'), 'network' => post('network'), 'interest' => mb_substr((string)post('interest'), 0, 1000), 'current_status' => post('current_status'), 'heard_from' => post('heard_from'), 'language' => post('language', 'en'), 'utm_source' => $_GET['utm_source'] ?? null, 'utm_medium' => $_GET['utm_medium'] ?? null, 'utm_campaign' => $_GET['utm_campaign'] ?? null, 'referrer' => mb_substr((string)($_SERVER['HTTP_REFERER'] ?? ''), 0, 300), 'landing_page' => 'membership', 'consent_correct' => 1, 'consent_updates' => post('consent_updates') ? 1 : 0]);
        send_mail(strtolower((string)post('email')), 'We received your interest in WODDI', '<p>Dear ' . e(post('full_name')) . ',</p><p>Thank you for your interest in the Women of Divine Destiny Initiative. Our team will be in touch. When admissions open you can register at ' . e(url('register')) . '.</p><p>WODDI Institute</p>');
        redirect('membership', ['done' => 1]);
    }
    if (!empty($_GET['done'])) public_shell('Membership', '<div class="col center"><span class="ic l big">' . ic('fa-check') . '</span><h1>Thank you</h1><p class="mut">We have your details and will be in touch.</p><a class="b au-b" href="' . url('register') . '">Create my learning account</a></div>');
    public_shell('Membership', '<form method="post" class="col" style="gap:14px">' . csrf_field() . '<h1>Join the WODDI family</h1><p class="mut">Tell us a little about you. It takes two minutes.</p><input name="website" tabindex="-1" autocomplete="off" style="position:absolute;left:-9999px" aria-hidden="true"><div class="g2"><label class="fld">Full name<input class="au-inp" name="full_name" required></label><label class="fld">Email<input class="au-inp" type="email" name="email" required></label><label class="fld">Phone or WhatsApp<input class="au-inp" name="phone"></label><label class="fld">Date of birth<input class="au-inp" type="date" name="dob"></label><label class="fld">Country<input class="au-inp" name="country" required></label><label class="fld">State or region<input class="au-inp" name="state"></label><label class="fld">Which network fits you?<select class="au-inp" name="network"><option value="WGMN">WODDI Good Mother Network (30 and above)</option><option value="WNNN">WODDI Nurture NextGen Network (18 to 29)</option><option value="unsure">I am not sure</option></select></label><label class="fld">What do you do now?<select class="au-inp" name="current_status"><option>Working</option><option>Business owner</option><option>Student</option><option>Homemaker</option><option>Looking for work</option><option>Other</option></select></label></div><label class="fld">What would you like to gain?<textarea class="au-inp" name="interest" rows="3"></textarea></label><label class="fld">How did you hear about WODDI?<input class="au-inp" name="heard_from"></label><label class="row rt"><input type="checkbox" name="consent_correct" value="1" required style="width:22px;height:22px;flex:none"><span class="sm">I confirm these details are correct and I agree to the <a href="' . url('privacy') . '" style="text-decoration:underline">privacy policy</a>.</span></label><label class="row rt"><input type="checkbox" name="consent_updates" value="1" style="width:22px;height:22px;flex:none"><span class="sm">Send me WODDI updates.</span></label><button class="b au-b">Send my details</button></form>');
}

if ($first === 'volunteer') {
    $roles = ['Country Representative', 'State or Regional Coordinator', 'Chapter Leader', 'Mentor', 'Facilitator or Trainer', 'Communications and Media', 'Programmes Support', 'Technology Support', 'Welfare and Outreach', 'Other'];
    if (is_post()) {
        if (post('website') !== '') redirect('volunteer', ['done' => 'X']);
        if (!filter_var(post('email'), FILTER_VALIDATE_EMAIL) || trim((string)post('full_name')) === '' || !post('affirm_true') || !post('agree')) { flash('Add your name, a valid email, and tick both confirmation boxes.', 'err'); redirect('volunteer'); }
        $ref = 'WV-' . gmdate('y') . '-' . strtoupper(substr(bin2hex(random_bytes(4)), 0, 6)); $up = fn(string $f) => (function () use ($f) { if (empty($_FILES[$f]['tmp_name']) || $_FILES[$f]['size'] > 5 * 1024 * 1024) return null; $ext = strtolower(pathinfo((string)$_FILES[$f]['name'], PATHINFO_EXTENSION)); if (!in_array($ext, ['pdf', 'jpg', 'jpeg', 'png', 'doc', 'docx'], true)) return null; @mkdir(APP_ROOT . '/uploads/volunteers', 0755, true); $fn = 'uploads/volunteers/' . bin2hex(random_bytes(10)) . '.' . $ext; return move_uploaded_file($_FILES[$f]['tmp_name'], APP_ROOT . '/' . $fn) ? url($fn) : null; })();
        $d = ['uid' => uid(), 'app_ref' => $ref, 'status' => 'new', 'proceed' => 1, 'affirm_true' => 1, 'agree' => 1, 'cv_url' => $up('cv'), 'id_url' => $up('idfile')];
        foreach (['network', 'role', 'chapter_interest', 'chapter_name', 'full_name', 'gender', 'dob', 'phone', 'country', 'state_region', 'lga_city', 'city_area', 'education', 'edu_field', 'experience', 'skills', 'languages', 'social', 'why', 'value', 'hours', 'reference', 'marital_status'] as $k) $d[$k] = mb_substr((string)post($k), 0, 3000) ?: null;
        $d['email'] = strtolower((string)post('email')); $d['is_mother'] = post('is_mother') ? 1 : 0; ins('volunteer_applications', $d);
        send_mail($d['email'], 'Your WODDI volunteer application ' . $ref, '<p>Dear ' . e($d['full_name']) . ',</p><p>We received your volunteer application. Your reference is <strong>' . $ref . '</strong>. The team will review it and write back to you.</p><p>WODDI</p>');
        redirect('volunteer', ['done' => $ref]);
    }
    if (!empty($_GET['done'])) public_shell('Volunteer', '<div class="col center"><span class="ic l big">' . ic('fa-check') . '</span><h1>Application received</h1><p class="mut">Your reference is <strong>' . e($_GET['done']) . '</strong>. Keep it safe. We will write to you by email.</p><a class="b au-b" href="' . url('') . '">Done</a></div>');
    $f = fn($n, $lab, $type = 'text', $req = false) => '<label class="fld">' . $lab . '<input class="au-inp" type="' . $type . '" name="' . $n . '"' . ($req ? ' required' : '') . '></label>';
    public_shell('Volunteer', '<form method="post" enctype="multipart/form-data" class="col" style="gap:14px">' . csrf_field() . '<h1>Volunteer with WODDI</h1><p class="mut">Leadership and service roles across Africa and the diaspora. Fill this in carefully. You can attach your CV.</p><input name="website" tabindex="-1" autocomplete="off" style="position:absolute;left:-9999px" aria-hidden="true"><h3>The role</h3><div class="g2"><label class="fld">Network<select class="au-inp" name="network"><option value="WGMN">WODDI Good Mother Network</option><option value="WNNN">WODDI Nurture NextGen Network</option></select></label><label class="fld">Role you are applying for<select class="au-inp" name="role" required><option value="">Choose a role</option>' . implode('', array_map(fn($r) => '<option>' . $r . '</option>', $roles)) . '</select></label>' . $f('chapter_name', 'Chapter or community (if any)') . $f('hours', 'Hours you can give each week') . '</div><h3>About you</h3><div class="g2">' . $f('full_name', 'Full name', 'text', true) . $f('email', 'Email', 'email', true) . $f('phone', 'Phone or WhatsApp', 'text', true) . $f('dob', 'Date of birth', 'date') . '<label class="fld">Gender<select class="au-inp" name="gender"><option>Female</option><option>Male</option></select></label><label class="fld">Marital status<select class="au-inp" name="marital_status"><option>Single</option><option>Married</option><option>Widowed</option><option>Prefer not to say</option></select></label>' . $f('country', 'Country', 'text', true) . $f('state_region', 'State or region') . $f('lga_city', 'LGA or city') . $f('languages', 'Languages you speak') . '</div><label class="row"><input type="checkbox" name="is_mother" value="1" style="width:22px;height:22px"> I am a mother</label><h3>Your background</h3><div class="g2">' . $f('education', 'Highest education') . $f('edu_field', 'Field of study') . '</div><label class="fld">Relevant experience<textarea class="au-inp" name="experience" rows="3"></textarea></label><label class="fld">Skills<textarea class="au-inp" name="skills" rows="2"></textarea></label><label class="fld">Why do you want to volunteer with WODDI?<textarea class="au-inp" name="why" rows="3" required></textarea></label><label class="fld">What value will you bring?<textarea class="au-inp" name="value" rows="2"></textarea></label><div class="g2">' . $f('social', 'Social media link') . $f('reference', 'A referee: name and phone') . '<label class="fld">CV (PDF or Word, up to 5 MB)<input class="au-inp" type="file" name="cv" accept=".pdf,.doc,.docx"></label><label class="fld">ID (PDF or photo, up to 5 MB)<input class="au-inp" type="file" name="idfile" accept=".pdf,.jpg,.jpeg,.png"></label></div><label class="row rt"><input type="checkbox" name="affirm_true" value="1" required style="width:22px;height:22px;flex:none"><span class="sm">Everything I have written is true.</span></label><label class="row rt"><input type="checkbox" name="agree" value="1" required style="width:22px;height:22px;flex:none"><span class="sm">I agree to the WODDI volunteer code of conduct and the <a href="' . url('privacy') . '" style="text-decoration:underline">privacy policy</a>.</span></label><button class="b au-b">Send my application</button></form>');
}

/* ───────── Academic Board review: a private link, no account needed ───────── */
if ($first === 'review') {
    $tok = (string)($_GET['token'] ?? ($_SESSION['review_token'] ?? '')); $S = $tok ? row('SELECT * FROM review_streams WHERE token = ? AND COALESCE(active,1) = 1 AND (expires_at IS NULL OR expires_at > ?)', [$tok, now()]) : null;
    if (!$S) public_shell('Course review', '<h1>This review link is not active</h1><p class="mut">The link may have expired or been switched off. Please ask the WODDI Institute team for a new one.</p>', 'Academic Board');
    $_SESSION['review_token'] = $tok; $name = (string)($_SESSION['reviewer'] ?? ''); $R = fn(array $q = []) => url('review', $q);
    if (is_post() && post('do') === 'name' && trim((string)post('name')) !== '') { $_SESSION['reviewer'] = mb_substr((string)post('name'), 0, 120); redirect('review'); }
    if ($name === '') public_shell('Course review', '<form method="post" class="col" style="gap:14px">' . csrf_field() . '<input type="hidden" name="do" value="name"><h1>' . e($S['name']) . '</h1><p class="mut">Welcome to the WODDI Institute Academic Board review. Your name is recorded beside every edit you propose, so the team knows who to thank and who to ask.</p><label class="fld">Your full name and title<input class="au-inp" name="name" required placeholder="Dr Ada Obi, Financial Inclusion Specialist"></label><button class="b au-b">Start reviewing</button></form>', 'Academic Board');
    $keys = array_column(rows('SELECT course_key FROM review_course_map WHERE stream_key = ?', [$S['stream_key']]), 'course_key'); $cid = (string)($_GET['c'] ?? '');
    if (is_post() && post('do') === 'edit' && in_array((string)post('course'), $keys, true)) {
        $orig = (string)($_POST['original'] ?? ''); $new = trim((string)($_POST['edited'] ?? '')); $c = (string)post('course'); $raw = (string)@file_get_contents(APP_ROOT . '/content/courses/' . $c . '.json');
        if ($orig === '' || $new === '' || $new === $orig) flash('Change the text before you send it.', 'err');
        elseif (!str_contains($raw, substr(json_encode($orig, JSON_UNESCAPED_UNICODE), 1, -1))) flash('That text could not be matched to the course. Please reload and try again.', 'err');
        else { ins('course_content_overrides', ['course_key' => $c, 'field' => mb_substr((string)post('field'), 0, 180), 'original_text' => $orig, 'edited_text' => mb_substr($new, 0, 8000), 'status' => 'draft', 'reviewer_name' => $name, 'stream_key' => $S['stream_key']]); try { ins('review_activity', ['stream_key' => $S['stream_key'], 'course_id' => $c, 'field' => mb_substr((string)post('field'), 0, 180), 'action' => 'proposed', 'reviewer_name' => $name]); } catch (Throwable $e) {} flash('Thank you. Your edit was sent to the WODDI team for approval.'); }
        redirect('review', ['c' => $c, 'm' => (int)post('m')]);
    }
    if (is_post() && post('do') === 'signoff' && in_array((string)post('course'), $keys, true)) { try { ins('review_activity', ['stream_key' => $S['stream_key'], 'course_id' => post('course'), 'field' => 'course', 'action' => post('verdict') === 'changes' ? 'changes_requested' : 'approved', 'reviewer_name' => $name]); } catch (Throwable $e) {} flash('Your verdict was recorded.'); redirect('review'); }
    $fl = implode('', array_map(fn($f) => '<div class="flash ' . e($f[0]) . '">' . e($f[1]) . '</div>', flash()));
    $shell = fn(string $inner) => page('Course review', '<div class="au-top"><img src="' . asset('logo.jpg') . '" alt="WODDI logo"><div class="grow"><b style="font-family:Manrope,sans-serif">Academic Board review</b><div class="xs mut">' . e($S['name']) . ', reviewing as ' . e($name) . '</div></div><a class="b g s" href="' . $R() . '">All courses</a></div><main class="cont" style="max-width:1000px;margin:0 auto;width:100%">' . $fl . $inner . '</main>', ['bare' => true]);
    if ($cid && in_array($cid, $keys, true) && ($co = course($cid))) {
        $mi = max(0, min(count($co['modules']) - 1, (int)($_GET['m'] ?? 0))); $M = $co['modules'][$mi];
        $ed = function (string $text, string $field) use ($cid, $mi) { $text = trim($text); if ($text === '') return ''; return '<details class="rv"><summary>' . inline($text) . '</summary><form method="post" class="col" style="gap:8px;margin-top:8px">' . csrf_field() . '<input type="hidden" name="do" value="edit"><input type="hidden" name="course" value="' . e($cid) . '"><input type="hidden" name="m" value="' . $mi . '"><input type="hidden" name="field" value="' . e($field) . '"><textarea name="original" hidden>' . e($text) . '</textarea><textarea class="inp" name="edited" rows="' . max(2, (int)ceil(mb_strlen($text) / 90)) . '">' . e($text) . '</textarea><button class="b s" style="align-self:flex-start">Propose this edit</button></form></details>'; };
        $pend = rows("SELECT field, edited_text, status, reviewer_name FROM course_content_overrides WHERE course_key = ? ORDER BY created_at DESC LIMIT 30", [$cid]);
        $h = '<div class="card col"><div class="row wrap">' . pill($co['level'] ?? '', 'n') . '<span class="mut sm">' . count($co['modules']) . ' modules</span></div><h1>' . e($co['title']) . '</h1><p class="mut">' . e($co['subtitle'] ?? '') . '</p><p class="sm">Tap any sentence to edit it. Your proposal goes to the WODDI team, and learners see it only after it is approved.</p></div><div class="chips">';
        foreach ($co['modules'] as $k => $m) $h .= '<a class="chip ' . ($k === $mi ? 'on' : '') . '" href="' . $R(['c' => $cid, 'm' => $k]) . '">Module ' . ($k + 1) . '</a>'; $h .= '</div><h2>' . e($M['title']) . '</h2>';
        foreach ($M['lessons'] as $li => $L) {
            $f = 'm' . ($mi + 1) . ' l' . ($li + 1); $h .= '<div class="card col"><p class="xs mut bold">LESSON ' . ($mi + 1) . '.' . ($li + 1) . '</p>' . $ed((string)$L['title'], "$f title");
            foreach (($L['objectives'] ?? []) as $o) $h .= $ed((string)$o, "$f objective");
            foreach (($L['blocks'] ?? []) as $b) { foreach (['text', 'title', 'body', 'caption'] as $k) if (!empty($b[$k]) && is_string($b[$k])) $h .= $ed($b[$k], "$f " . ($b['type'] ?? 'block') . " $k"); foreach (['items', 'steps'] as $k) foreach (($b[$k] ?? []) as $x) { if (is_string($x)) $h .= $ed($x, "$f " . ($b['type'] ?? 'block') . ' item'); elseif (is_array($x)) foreach ($x as $v) if (is_string($v) && mb_strlen($v) > 3) $h .= $ed($v, "$f " . ($b['type'] ?? 'block') . ' item'); } }
            foreach (($L['takeaways'] ?? []) as $o) $h .= $ed((string)$o, "$f takeaway");
            if (!empty($L['activity'])) { $h .= '<p class="xs mut bold">PRACTICE TASK</p>' . $ed((string)($L['activity']['title'] ?? ''), "$f task title"); foreach (($L['activity']['steps'] ?? []) as $x) $h .= $ed((string)$x, "$f task step"); }
            $h .= '</div>';
        }
        if (!empty($M['quiz'])) { $h .= '<div class="card col"><p class="xs mut bold">MODULE QUIZ</p>'; foreach ($M['quiz'] as $qi => $q1) { $h .= $ed((string)$q1['q'], 'm' . ($mi + 1) . ' quiz q' . ($qi + 1)); foreach ($q1['options'] as $oi => $o) $h .= '<div style="padding-left:18px">' . ((int)$q1['correct'] === $oi ? '<span class="pill l" style="float:right">Correct answer</span>' : '') . $ed((string)$o, 'm' . ($mi + 1) . ' quiz q' . ($qi + 1) . ' option') . '</div>'; if (!empty($q1['explain'])) $h .= $ed((string)$q1['explain'], 'm' . ($mi + 1) . ' quiz q' . ($qi + 1) . ' explanation'); } $h .= '</div>'; }
        if ($pend) { $h .= '<div class="card col"><h3>Edits proposed on this course</h3>'; foreach ($pend as $p) $h .= '<div class="row rt"><span class="grow sm"><strong>' . e($p['field']) . '</strong>: ' . e(mb_strimwidth((string)$p['edited_text'], 0, 160, '...')) . '<span class="mut xs" style="display:block">' . e($p['reviewer_name']) . '</span></span>' . pill(ucfirst((string)$p['status']), in_array($p['status'], ['applied', 'live'], true) ? 'l' : 'n') . '</div>'; $h .= '</div>'; }
        $h .= '<form method="post" class="card row wrap">' . csrf_field() . '<input type="hidden" name="do" value="signoff"><input type="hidden" name="course" value="' . e($cid) . '"><span class="grow"><span class="bold" style="display:block">Finished with this course?</span><span class="mut sm">Record your verdict for the WODDI team.</span></span><button class="b l s" name="verdict" value="approved">' . ic('fa-check') . ' Approve course</button><button class="b g s" name="verdict" value="changes">Needs changes</button></form>';
        $shell('<div class="col" style="gap:14px">' . $h . '</div>');
    }
    $act = []; foreach (rows("SELECT course_id, action FROM review_activity WHERE stream_key = ? ORDER BY created_at", [$S['stream_key']]) as $a) $act[$a['course_id']] = $a['action'];
    $edits = []; foreach (rows('SELECT course_key, COUNT(*) n FROM course_content_overrides WHERE stream_key = ? GROUP BY course_key', [$S['stream_key']]) as $r) $edits[$r['course_key']] = (int)$r['n'];
    $done = count(array_filter($act, fn($a) => in_array($a, ['approved', 'changes_requested'], true)));
    $h = '<div class="hero"><p class="kick">Academic Board</p><h1>' . e($S['name']) . '</h1><p class="soft">' . count($keys) . ' courses to review. ' . $done . ' have a verdict. Thank you for lending your expertise to WODDI learners.</p>' . bar($keys ? (int)round($done / count($keys) * 100) : 0) . '</div><div class="gc">';
    foreach ($keys as $k) { $it = catalog_item($k); if (!$it) continue; $a = $act[$k] ?? ''; $h .= '<a class="cc" href="' . $R(['c' => $k]) . '"><span class="row" style="gap:6px">' . pill($it['level'], 'n') . ($a === 'approved' ? pill('Approved', 'l') : ($a === 'changes_requested' ? pill('Needs changes', 'g') : ($a ? pill('In review') : ''))) . '</span><span class="bold grow">' . e($it['title']) . '</span><span class="xs mut">' . (int)$it['modules'] . ' modules, ' . (int)$it['lessons'] . ' lessons' . (!empty($edits[$k]) ? ', ' . $edits[$k] . ' edits proposed' : '') . '</span></a>'; }
    $shell('<div class="col" style="gap:14px">' . $h . '</div></div>');
}
